from typing import TypedDict

class T(TypedDict):
    field: object

def example() -> None:
    data: object = 0
    data = data["field"] = T(field=1)

class Descriptor:
    def __set__(self, instance: object, value: object) -> None:
        pass

    def __get__(self, instance: object, owner: type[object] | None = None) -> object:
        return self

class Box:
    field = Descriptor()

def example() -> None:
    obj: object = 0
    obj = obj.field = Box()

